mapper.select:
select u.user_id, u.dept_id, u.nick_name, u.user_name, u.email, u.avatar, u.phonenumber, u.sex, u.status, u.del_flag, u.login_ip, u.login_date, u.create_by, u.create_time, u.remark, d.dept_name, d.leader from sys_user u left join sys_dept d on u.dept_id = d.dept_id where u.del_flag = '0'
AND u.user_id = #{userId}
AND (u.user_name like concat('%', #{userName}, '%') or u.nick_name like concat('%', #{userName}, '%'))
AND u.status = #{status}
AND u.phonenumber like concat('%', #{phonenumber}, '%')
AND date_format(u.create_time,'%Y%m%d') >= date_format(#{params.beginTime},'%Y%m%d')
AND date_format(u.create_time,'%Y%m%d') <= date_format(#{params.endTime},'%Y%m%d')
AND (u.dept_id = #{deptId} OR u.dept_id IN ( SELECT t.dept_id FROM sys_dept t WHERE find_in_set(#{deptId}, ancestors) ))
${params.dataScope}

select distinct u.user_id, u.dept_id, u.user_name, u.nick_name, u.email, u.phonenumber, u.status, u.create_time from sys_user u left join sys_dept d on u.dept_id = d.dept_id left join sys_user_role ur on u.user_id = ur.user_id left join sys_role r on r.role_id = ur.role_id where u.del_flag = '0' and r.role_id = #{roleId}
AND u.user_name like concat('%', #{userName}, '%')
AND u.phonenumber like concat('%', #{phonenumber}, '%')
${params.dataScope}

select u.* from sys_user u left join neucity_device_registration dr on u.`code` = dr.device_code where u.code is not null
and dr.device_type_code in
#{item}

select u.* from sys_user u left join neucity_device_bind_space dr on u.`code` = dr.device_code where u.code is not null
and dr.space_code in
#{item}

select u.user_id, u.user_name, u.nick_name, u.avatar, u.staff_categ_name, u.major_skill_post_name, d.dept_name, c.role_id from sys_user u left join sys_dept d on u.dept_id = d.dept_id left join sys_user_role c on u.user_id = c.user_id
AND (u.dept_id = #{deptId} or find_in_set(#{deptId} , ancestors ))
AND u.user_id != #{notUserId}
AND c.role_id != #{notRoleId}
AND (u.login_device != #{notLoginDevice} or u.login_device is null)
AND (u.user_name like concat('%', #{username}, '%') or u.nick_name like concat('%', #{username}, '%'))
AND u.user_id IN
#{userId}
order by u.login_date desc

select u.* from sys_user u
left join sys_user_role ur on u.user_id = ur.user_id
where ur.role_id = #{roleId}

