dept_id = #{deptId}, nick_name = #{nickName}, email = #{email}, phonenumber = #{phonenumber}, sex = #{sex}, avatar = #{avatar}, password = #{password}, status = #{status}, login_ip = #{loginIp}, login_date = #{loginDate}, update_by = #{updateBy}, remark = #{remark}, bed_number = #{bedNumber}, pin_yin = #{pinYin}, face_code = #{faceCode}, face_img = #{faceImg}, room_no = #{roomNo}, agent_name = #{agentName}, update_time = sysdate()
where user_id = #{userId}

update sys_user
dept_id = #{deptId}, nick_name = #{nickName}, email = #{email}, phonenumber = #{phonenumber}, sex = #{sex}, avatar = #{avatar}, password = #{password}, status = #{status}, login_ip = #{loginIp}, login_date = #{loginDate}, update_by = #{updateBy}, remark = #{remark}, bed_number = #{bedNumber}, pin_yin = #{pinYin}, face_code = #{faceCode}, face_img = #{faceImg}, agent_name = #{agentName}, update_time = sysdate()
where code = #{code}
